#include <cstdio>
#include <algorithm>

int main()
{
    int N, M;
    long long X;

    if (scanf("%d %d %lld", &N, &M, &X) != 3)
        return 0;

    long long squares = 0;

    for (int a = 0; a < N; ++a)
    {
        for (int b = 0; b < M; ++b)
        {
            long long count = 0;

            if ((a & 1) == (b & 1))
            {
                count = 1LL + std::min(
                    std::min(a, N - 1 - a),
                    std::min(b, M - 1 - b)
                );
            }

            if (count == X)
                ++squares;
        }
    }

    printf("%lld", squares);
    return 0;
}

