#include <algorithm>
#include <iostream>

int main() {
    int N, M;
    long long X;
    std::cin >> N >> M >> X;

    long long squares = 0;

    for (int a = 0; a < N; ++a) {
        for (int b = 0; b < M; ++b) {
            long long count = 0;

            if ((a & 1) == (b & 1)) {
                count = std::min({
                    a + 1,
                    N - a,
                    b + 1,
                    M - b
                });
            }

            if (count == X) {
                ++squares;
            }
        }
    }

    std::cout << squares;
    return 0;
}

